def read_name(record):
    try:
        return record["name"]
    except KeyError:
        return "Missing name"

print(read_name({"name": "Subo"}))
print(read_name({}))
try:
    read_name(None)
except TypeError:
    print("Wrong input type remains visible")

# Synthetic statuses: no network requests are made.
def classify(status):
    if 200 <= status < 300:
        return "check payload"
    if status == 429:
        return "consider bounded retry"
    if status in (401, 403):
        return "check access; do not blindly retry"
    return "handle explicit failure"

for status in [200, 403, 429, 500]:
    print(status, classify(status))

from itertools import islice

def batches(iterable, size):
    if isinstance(size, bool) or not isinstance(size, int) or size < 1:
        raise ValueError("size must be a positive integer")
    items = iter(iterable)
    while True:
        batch = list(islice(items, size))
        if not batch:
            return
        yield batch

print(list(batches(range(5), 2)))
print(list(batches([], 2)))
try:
    list(batches(range(3), 0))
except ValueError:
    print("Rejected invalid size")

