function batches(items, size) {
  if (!Array.isArray(items)) throw new TypeError('items must be an array');
  if (!Number.isInteger(size) || size < 1) throw new RangeError('positive integer required');
  const output = [];
  for (let i = 0; i < items.length; i += size) output.push(items.slice(i, i + size));
  return output;
}
const input = [1, 2, 3, 4, 5];
console.log(JSON.stringify(batches(input, 2)));
console.log(JSON.stringify(batches([], 2)));
console.log(JSON.stringify(input));
try { batches(input, 0); } catch (error) { console.log(error.name); }

// Standalone transition helper; network work belongs outside it.
function reducer(state, action) {
  if (action.type === 'start') return { status: 'saving', requestId: action.id };
  if (action.type === 'success' && state.status === 'saving' && state.requestId === action.id) {
    return { status: 'success', receipt: action.receipt };
  }
  return state;
}
let state = reducer({ status: 'idle' }, { type: 'start', id: 2 });
state = reducer(state, { type: 'success', id: 1, receipt: 'stale' });
console.log(state.status);
state = reducer(state, { type: 'success', id: 2, receipt: 'saved' });
console.log(state.status, state.receipt);

// Standalone store core; a React UI would subscribe with useSyncExternalStore.
function createStore() {
  let snapshot = Object.freeze({ count: 0 });
  const listeners = new Set();
  return {
    getSnapshot: () => snapshot,
    subscribe(listener) { listeners.add(listener); return () => listeners.delete(listener); },
    increment() { snapshot = Object.freeze({ count: snapshot.count + 1 }); for (const fn of listeners) fn(); }
  };
}
const store = createStore();
const before = store.getSnapshot();
console.log(before === store.getSnapshot());
let calls = 0;
const unsubscribe = store.subscribe(() => calls++);
store.increment();
unsubscribe();
store.increment();
console.log(before.count, store.getSnapshot().count, calls);
console.log(before === store.getSnapshot());

// In-memory fixed snapshot only; a real API validates its cursor and ownership.
const rows = [{ time: 10, id: 2 }, { time: 9, id: 3 }, { time: 10, id: 1 }];
const ordered = [...rows].sort((a, b) => a.time - b.time || a.id - b.id);
const cursor = { time: 10, id: 1 };
const next = ordered.filter(r => r.time > cursor.time || (r.time === cursor.time && r.id > cursor.id));
console.log(JSON.stringify(ordered.map(r => r.id)));
console.log(JSON.stringify(next.map(r => r.id)));

// Complete record events with monotonic versions; not a resume protocol.
function apply(current, event) {
  if (current && event.version <= current.version) return current;
  return Object.freeze({ ...event });
}
let state = apply(null, { version: 5, value: 'current', deleted: false });
state = apply(state, { version: 4, value: 'stale', deleted: false });
console.log(state.version, state.value);
state = apply(state, { version: 6, value: null, deleted: true });
state = apply(state, { version: 5, value: 'late', deleted: false });
console.log(state.version, state.deleted);
